import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ORDER = ['rd', 'manufacturing', 'quality', 'regulatory', 'supply', 'commercial', 'hospital', 'community', 'safety']
KEYS = ['title', 'area', 'short', 'symptom', 'ingredient', 'directions', 'problem', 'why', 'solution', 'architecture', 'data', 'technology', 'impact', 'limitations', 'review']

def P(slug, field, k, tags, phase, en, ar, refs=()):
    assert set(en) == set(KEYS) and set(ar) == set(KEYS), slug
    d = dict(slug=slug, field=field, order=ORDER.index(field) * 10 + k, phase=phase, status='Conceptual', techTags=tags,
             references=[{'title': t, 'url': u} for t, u in refs], screenshots=[], video='', seoTitle='', seoDescription='', **en)
    json.dump(d, open(os.path.join(ROOT, 'content/projects', slug + '.json'), 'w'), indent=2, ensure_ascii=False)
    json.dump({'slug': slug, **ar}, open(os.path.join(ROOT, 'content/ar/projects', slug + '.json'), 'w'), indent=2, ensure_ascii=False)

